-- capitec-bank-delft-mall-delft (owner)
UPDATE businesses SET description = 'Capitec Bank''s Delft Mall branch, at Shop 34 in Delft Mall on Hindle Road, offers simple, affordable everyday banking to residents of Delft and the surrounding areas. Its consultants help clients open accounts, start saving, apply for personal loans and look at insurance options, all explained in plain language so customers know exactly what they are signing up for.

Day-to-day transactions can be handled in the branch with the help of staff, and clients are shown how to manage their money through Capitec''s digital banking so they can make payments and check balances from their phones. ATMs nearby make it easy to draw cash while shopping in the mall. With its focus on low fees and straightforward products, the branch is a practical choice for households that want banking to be easy and transparent. Capitec is at Shop 34, Delft Mall, Hindle Road, Delft.', description_enriched_at = datetime('now') WHERE slug = 'capitec-bank-delft-mall-delft' AND description = 'Capitec Bank is a bank branch inside Delft Mall, offering everyday banking services to shoppers in Delft.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- esacks-pharmacy-hanover-park (owner)
UPDATE businesses SET description = 'Esack''s Pharmacy is an independent pharmacy in the Town Centre on Surran Road, at the commercial heart of Hanover Park. It is an important local healthcare resource, giving residents easy access to prescriptions, everyday medicines and health advice without travelling out of the area.

Patients can have their doctor''s prescriptions filled, buy over-the-counter remedies and choose from a range of affordable wellness products. The pharmacy team is knowledgeable and approachable, offering personal health advice, routine blood pressure checks and basic clinic services for common health concerns. Being in the busy town centre means families can look after their health needs while doing their regular shopping, whether that is collecting monthly medication or picking up something for a child''s cough. For Hanover Park households, it is a dependable neighbourhood pharmacy close to home. Esack''s Pharmacy is at Shop 6b, Town Centre, Surran Road, Hanover Park.', description_enriched_at = datetime('now') WHERE slug = 'esacks-pharmacy-hanover-park' AND description = 'Esack''s Pharmacy is a pharmacy in Hanover Park, operating from Shop 6b in the Town Centre on Surran Road.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
